const all = $input.all();
const limited = all.slice(0, 3);
return limited;

const all = $input.all();
const orders = all.map(i => i.json);
// Datos del formulario público de cotización: se escapan antes de insertarlos en HTML.
const esc = v => String(v ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch]);
const fecha = new Date().toLocaleDateString('es-AR', { day:'2-digit', month:'long', year:'numeric' });

// Un PDF de remito por orden: remito_1, remito_2, ... (el nodo Gmail los adjunta por nombre).
const binary = {};
const remitos = [];
all.forEach((it) => {
  const pdf = it.binary && it.binary.data;
  if (!pdf) return;
  binary['remito_' + (remitos.length + 1)] = pdf;
  remitos.push({ order_id: it.json.id, archivo: pdf.fileName });
});

const rows = orders.map(o =>
  `<tr>
    <td style="padding:6px 12px;border-bottom:1px solid #e5e7eb;">#${esc(o.id)}</td>
    <td style="padding:6px 12px;border-bottom:1px solid #e5e7eb;">${esc(o.customer_nombre)}</td>
    <td style="padding:6px 12px;border-bottom:1px solid #e5e7eb;">${o.localidad ? esc(o.localidad) : 'Sin informar'}</td>
    <td style="padding:6px 12px;border-bottom:1px solid #e5e7eb;text-align:right;">${o.total?.toLocaleString('es-AR')} u.</td>
  </tr>`
).join('');

const adjuntos_html = remitos.length
  ? `<p>Remitos adjuntos (PDF): ${remitos.map(r => `<code>${esc(r.archivo)}</code>`).join(', ')}</p>`
  : '';

const summary_html = `
<div style="font-family:sans-serif;max-width:680px;margin:0 auto;padding:24px;">
  <h2 style="color:#166534;">Golden Harvest S.A. — Resumen de despacho</h2>
  <p style="color:#6b7280;">Fecha: ${fecha}</p>
  <p>Se procesaron <strong>${orders.length}</strong> orden(es) confirmada(s):</p>
  <table style="width:100%;border-collapse:collapse;font-size:14px;">
    <thead><tr style="background:#f3f4f6;">
      <th style="padding:8px 12px;text-align:left;">Orden</th>
      <th style="padding:8px 12px;text-align:left;">Cliente</th>
      <th style="padding:8px 12px;text-align:left;">Localidad</th>
      <th style="padding:8px 12px;text-align:right;">Unidades</th>
    </tr></thead>
    <tbody>${rows}</tbody>
  </table>
  ${adjuntos_html}
  <p style="margin-top:20px;font-size:12px;color:#9ca3af;">Golden Harvest S.A. — Sistema Automatizado de Logística</p>
</div>`;

return [{
  json: { summary_html, total: orders.length, fecha: new Date().toISOString().slice(0,10), remitos, adjuntos: Object.keys(binary).join(',') },
  binary,
}];

// El backend entrega sus webhooks con at-least-once (outbox): puede repetir el mismo evento.
// Cada POST trae el header Idempotency-Key (p. ej. "order:<id>:confirmed"). Se recuerdan las
// últimas 500 claves en el static data del workflow (solo persiste en ejecuciones de producción,
// es decir con el workflow activo); una clave ya vista marca el ítem como duplicado.
const MAX_KEYS = 500;
const json = $input.item.json;
const headers = json.headers || {};
const key = headers['idempotency-key'] || headers['Idempotency-Key'] || null;
if (!key) return { json: { ...json, idempotency_key: null, duplicate: false } };
const store = $getWorkflowStaticData('global');
const seen = Array.isArray(store.seenKeys) ? store.seenKeys : [];
if (seen.includes(key)) return { json: { ...json, idempotency_key: key, duplicate: true } };
seen.push(key);
store.seenKeys = seen.slice(-MAX_KEYS);
return { json: { ...json, idempotency_key: key, duplicate: false } };

// Contrato del backend (backend/src/routes/quotes.ts, evento order.confirmed, N8N_LOGISTICS_WEBHOOK):
// { orderId, quoteId, contact: { nombre, empresa?, telefono?, email, notas?, localidad? },
//   items: [{ id, name, line, size, qty }] }
const b = $input.item.json.body;
const bad = (error) => ({ json: { valid: false, error } });
const str = (v) => typeof v === 'string' && v.trim() !== '';
if (!b || typeof b !== 'object' || Array.isArray(b)) return bad('body: se esperaba un objeto JSON');
if (!str(b.orderId)) return bad('orderId: texto requerido');
const c = b.contact;
if (!c || typeof c !== 'object') return bad('contact: objeto requerido');
if (!str(c.nombre)) return bad('contact.nombre: texto requerido');
if (!Array.isArray(b.items) || b.items.length === 0) return bad('items: se esperaba un arreglo con al menos un producto');
if (b.items.length > 200) return bad('items: demasiados productos (máximo 200)');
const items = [];
for (let i = 0; i < b.items.length; i++) {
  const it = b.items[i];
  if (!it || typeof it !== 'object') return bad(`items[${i}]: no es un objeto`);
  if (!str(it.name)) return bad(`items[${i}].name: texto requerido`);
  if (!str(it.size)) return bad(`items[${i}].size: texto requerido`);
  if (!Number.isInteger(it.qty) || it.qty < 1) return bad(`items[${i}].qty: entero >= 1 requerido`);
  items.push({ name: it.name, size: it.size, qty: it.qty, line: typeof it.line === 'string' ? it.line : '' });
}
const opt = (v) => (typeof v === 'string' && v.trim() !== '' ? v.trim() : null);
return { json: {
  valid: true,
  id: b.orderId,
  quote_id: opt(b.quoteId),
  customer_nombre: c.nombre,
  customer_empresa: opt(c.empresa),
  customer_telefono: opt(c.telefono),
  customer_email: opt(c.email),
  localidad: opt(c.localidad),
  total: items.reduce((s, i) => s + i.qty, 0),
  items,
  fecha_orden: new Date().toISOString(),
  origen: 'webhook',
} };

// Camino manual: GET /api/orders no trae los productos; se piden por orden a
// GET /api/orders/:id/items (misma X-Service-Key) para poder armar el remito.
const BASE = 'http://backend:3001/api';
const out = [];
for (const { json: o } of $input.all()) {
  let items = [];
  let items_error;
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: `${BASE}/orders/${encodeURIComponent(o.id)}/items`,
      headers: { 'X-Service-Key': $env.SERVICE_API_KEY },
      json: true,
    });
    items = (Array.isArray(res) ? res : []).map((i) => ({
      name: i.nombre || i.product_name || '',
      size: i.size ?? '',
      qty: i.cantidad,
      line: i.product_line ?? '',
    }));
  } catch (e) {
    items_error = String(e && e.message ? e.message : e);
  }
  out.push({ json: {
    id: o.id,
    customer_nombre: o.customer_nombre,
    customer_empresa: null,
    customer_telefono: null,
    customer_email: o.customer_email ?? null,
    localidad: o.localidad ?? null,
    total: o.total,
    items,
    ...(items_error ? { items_error } : {}),
    fecha_orden: o.createdAt ?? new Date().toISOString(),
    origen: 'api',
  } });
}
return out;

// Remito de entrega (demo académica) como HTML -> data: URL; el nodo Puppeteer lo convierte en PDF.
const o = $input.item.json;
// Datos del formulario público de cotización: se escapan antes de insertarlos en HTML.
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch]);
const LINE = { roja: 'Línea Roja', dorada: 'Línea Dorada' };
const fecha = new Date(o.fecha_orden || Date.now()).toLocaleDateString('es-AR', { day: '2-digit', month: 'long', year: 'numeric' });
const items = Array.isArray(o.items) ? o.items : [];
const unidades = items.length ? items.reduce((s, i) => s + (Number(i.qty) || 0), 0) : Number(o.total) || 0;
const th = 'padding:8px 10px;text-align:left;border-bottom:2px solid #166534;';
const td = 'padding:7px 10px;border-bottom:1px solid #e5e7eb;';
const filas = items.length
  ? items.map((i) => `<tr><td style="${td}">${esc(i.name)}</td><td style="${td}">${esc(LINE[String(i.line).toLowerCase()] ?? i.line)}</td><td style="${td}">${esc(i.size)}</td><td style="${td}text-align:right;">${esc(i.qty)}</td></tr>`).join('')
  : `<tr><td colspan="4" style="${td}color:#6b7280;">Detalle de ítems no disponible</td></tr>`;
const dato = (etq, val) => (val ? `<p style="margin:2px 0;"><strong>${etq}:</strong> ${esc(val)}</p>` : '');
const remito_html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Remito ${esc(o.id)}</title></head><body style="font-family:Arial,sans-serif;font-size:13px;color:#111;margin:0;padding:32px;">
<div style="display:flex;justify-content:space-between;border-bottom:3px solid #166534;padding-bottom:12px;">
  <div><h1 style="margin:0;color:#166534;font-size:22px;">Golden Harvest S.A.</h1><p style="margin:2px 0;color:#6b7280;">Remito de entrega</p></div>
  <div style="text-align:right;"><p style="margin:2px 0;"><strong>Remito — Orden #${esc(o.id)}</strong></p><p style="margin:2px 0;">Fecha: ${fecha}</p></div>
</div>
<div style="margin:18px 0;">
  ${dato('Cliente', o.customer_nombre)}${dato('Empresa', o.customer_empresa)}${dato('Email', o.customer_email)}${dato('Teléfono', o.customer_telefono)}
  <p style="margin:2px 0;"><strong>Localidad de entrega:</strong> <span>${o.localidad ? esc(o.localidad) : 'Sin informar'}</span></p>
</div>
<table style="width:100%;border-collapse:collapse;"><thead><tr><th style="${th}">Producto</th><th style="${th}">Línea</th><th style="${th}">Presentación</th><th style="${th}text-align:right;">Unidades</th></tr></thead><tbody>${filas}</tbody></table>
<p style="text-align:right;font-size:15px;margin-top:14px;"><strong>Total: ${unidades} unidades</strong></p>
<div style="margin-top:48px;display:flex;justify-content:space-between;color:#6b7280;"><span>Firma y aclaración del receptor: ____________________</span><span>Fecha de recepción: ___ / ___ / ______</span></div>
<p style="margin-top:36px;padding:8px;border:2px dashed #b91c1c;color:#b91c1c;text-align:center;font-weight:bold;">Documento no válido como factura — demo académica</p>
</body></html>`;
const remito_url = 'data:text/html;charset=utf-8;base64,' + Buffer.from(remito_html, 'utf8').toString('base64');
return { json: { ...o, remito_html, remito_url } };

// El nodo Puppeteer devuelve solo { headers, statusCode, url } + el PDF: se recupera la orden
// del nodo anterior (mismo ítem) y se nombra el archivo por id de orden.
const src = $('Armar Remito HTML').item.json;
const { remito_html, remito_url, ...order } = src;
const pdf = $input.item.binary && $input.item.binary.data;
if (!pdf) throw new Error('Puppeteer no devolvió el PDF del remito de la orden ' + order.id);
pdf.fileName = `remito-${order.id}.pdf`;
pdf.mimeType = 'application/pdf';
return { json: order, binary: { data: pdf } };
